#!/usr/bin/env bash
#
# Build a distributable zip of the Shitate theme.
# Stages only the files that ship and zips them with the theme slug as the
# top-level folder (required for WordPress installs).
#
set -euo pipefail

cd "$(dirname "$0")/.."

SLUG="shitate"
DIST="dist"
STAGE="$DIST/$SLUG"

# Guard: the translation catalogs are generated by a script in another repo
# (plugins/shitate-pro-blocks/bin/make-i18n.mjs). If that script runs without
# the theme's dictionary it silently writes empty catalogs, so refuse to ship
# a .mo that is (almost) empty or a ja.po with no translations.
for mo in languages/*.mo; do
	if [ "$(wc -c < "$mo" | tr -d ' ')" -lt 1000 ]; then
		echo "✗ $mo is nearly empty ($(wc -c < "$mo" | tr -d ' ') bytes) — regenerate the translations before building"
		exit 1
	fi
done
if [ "$(grep -c '^msgstr ""$' languages/shitate-ja.po)" -gt 3 ]; then
	echo "✗ languages/shitate-ja.po has untranslated strings — regenerate the translations before building"
	echo "  (if the strings belong to patterns listed in bin/deferred-patterns.txt, run bin/trim-deferred-i18n.mjs)"
	exit 1
fi

echo "→ Staging files…"
rm -rf "$STAGE" "$DIST/$SLUG.zip"
mkdir -p "$STAGE"

for item in style.css theme.json functions.php readme.txt screenshot.png templates parts patterns styles assets inc languages; do
	if [ -e "$item" ]; then
		cp -R "$item" "$STAGE/"
	fi
done

# Patterns held back from this release stay in the repo but must not reach the
# zip: the translation catalogs are built for the shipped file set only, so a
# pattern that ships without its strings would render untranslated.
while IFS= read -r line || [ -n "$line" ]; do
	name="${line%%#*}"
	name="${name// /}"
	name="${name//$'\t'/}"
	[ -n "$name" ] || continue
	if [ ! -e "$STAGE/patterns/$name" ]; then
		echo "✗ bin/deferred-patterns.txt lists patterns/$name but the theme has no such file — update the list"
		rm -rf "$STAGE"
		exit 1
	fi
	rm "$STAGE/patterns/$name"
	echo "  held back: patterns/$name"
done < bin/deferred-patterns.txt

find "$STAGE" -name ".DS_Store" -delete

echo "→ Zipping…"
( cd "$DIST" && zip -rqX "$SLUG.zip" "$SLUG" )
rm -rf "$STAGE"

echo "✓ Built $DIST/$SLUG.zip"
